"use strict";(self.webpackChunkcoursesmith_site=self.webpackChunkcoursesmith_site||[]).push([["6459"],{7242(e,t,n){n.r(t),n.d(t,{metadata:()=>s,default:()=>c,frontMatter:()=>i,contentTitle:()=>r,toc:()=>l,assets:()=>h});var s=JSON.parse('{"id":"m1-how-llms-work/deep-dive","title":"Deep Dive \u2014 Attention, Sampling & the Hidden Chat Contract","description":"The lab proved the two phases exist and let you time them. It showed tokens as the meter and the KV cache as the memory bill. This page goes below that. You will build a working feel for what attention actually does (the reason the KV cache holds keys and values), you will see why \\"set temperature to 0 for reproducible evals\\" is a half-truth that will burn you when you compare two engines, and you will read the chat template \u2014 the hidden wrapper every one of your messages goes through before the model ever sees it. These are the layers you reach for when an eval that passed yesterday fails today with no code change, or when a model that worked on Ollama gives different answers on vLLM.","source":"@site/docs/m1-how-llms-work/deep-dive.md","sourceDirName":"m1-how-llms-work","slug":"/m1-how-llms-work/deep-dive","permalink":"/305-llmops/docs/m1-how-llms-work/deep-dive","draft":false,"unlisted":false,"tags":[],"version":"current","sidebarPosition":4,"frontMatter":{"sidebar_position":4,"title":"Deep Dive \u2014 Attention, Sampling & the Hidden Chat Contract","sidebar_label":"Deep Dive (Part 2)"},"sidebar":"courseSidebar","previous":{"title":"Quiz: How LLMs Work \u2014 Tokens, Prefill/Decode & the KV Cache","permalink":"/305-llmops/docs/m1-how-llms-work/quiz"},"next":{"title":"Lesson: Models, Quantization & the OpenAI-Compatible Contract","permalink":"/305-llmops/docs/m2-models-quantization-api/lesson"}}'),a=n(4848),o=n(8453);let i={sidebar_position:4,title:"Deep Dive \u2014 Attention, Sampling & the Hidden Chat Contract",sidebar_label:"Deep Dive (Part 2)"},r="Deep Dive \u2014 Attention, Sampling & the Hidden Chat Contract",h={},l=[{value:"1 \u2014 Attention, without the maths wall",id:"1--attention-without-the-maths-wall",level:2},{value:"2 \u2014 Temperature 0 is not &quot;reproducible&quot;",id:"2--temperature-0-is-not-reproducible",level:2},{value:"3 \u2014 The chat template: the wrapper you never see",id:"3--the-chat-template-the-wrapper-you-never-see",level:2},{value:"4 \u2014 Thinking mode, one level down",id:"4--thinking-mode-one-level-down",level:2},{value:"Teardown",id:"teardown",level:2}];function d(e){let t={admonition:"admonition",code:"code",em:"em",h1:"h1",h2:"h2",header:"header",li:"li",mermaid:"mermaid",p:"p",pre:"pre",strong:"strong",ul:"ul",...(0,o.R)(),...e.components};return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsx)(t.header,{children:(0,a.jsx)(t.h1,{id:"deep-dive--attention-sampling--the-hidden-chat-contract",children:"Deep Dive \u2014 Attention, Sampling & the Hidden Chat Contract"})}),"\n",(0,a.jsxs)(t.p,{children:["The lab proved the two phases exist and let you time them. It showed tokens as the meter and the KV cache as the memory bill. This page goes below that. You will build a working feel for what attention actually does (the reason the KV cache holds ",(0,a.jsx)(t.em,{children:"keys"})," and ",(0,a.jsx)(t.em,{children:"values"}),'), you will see why "set temperature to 0 for reproducible evals" is a half-truth that will burn you when you compare two engines, and you will read the chat template \u2014 the hidden wrapper every one of your messages goes through before the model ever sees it. These are the layers you reach for when an eval that passed yesterday fails today with no code change, or when a model that worked on Ollama gives different answers on vLLM.']}),"\n",(0,a.jsx)(t.admonition,{title:"Where this picks up",type:"info",children:(0,a.jsxs)(t.p,{children:["You need the same setup as the lab: Ollama running on the host and ",(0,a.jsx)(t.code,{children:"qwen3:0.6b"})," pulled. If you did the lab teardown, nothing is lost \u2014 Ollama is still your host model server. Re-running any command here is safe; none of them change persistent state. If the model was idle, the first request pays the one-time load again (the keep-alive clock from the lab). That is all."]})}),"\n",(0,a.jsx)(t.h2,{id:"1--attention-without-the-maths-wall",children:"1 \u2014 Attention, without the maths wall"}),"\n",(0,a.jsxs)(t.p,{children:['The lesson said attention lets each token "look back" at the earlier ones. Here is the working picture of ',(0,a.jsx)(t.em,{children:"how"}),", and it is the reason the cache is called the ",(0,a.jsx)(t.strong,{children:"KV"})," cache specifically."]}),"\n",(0,a.jsxs)(t.p,{children:["Think of a room of people, each holding a small sign (a ",(0,a.jsx)(t.strong,{children:"key"}),") that says what they are about, and a note in their pocket (a ",(0,a.jsx)(t.strong,{children:"value"}),") with the actual content they would hand over. A new person walks in with a question written on their forehead (a ",(0,a.jsx)(t.strong,{children:"query"}),"). They glance around, match their query against everyone's key sign, and the closer the match, the more they lean in and read that person's note. Their next move is a blend of the notes, weighted by how well each key matched their query. That is attention: query matches keys, and the matched values get blended. Query, key, value \u2014 the three come from every token."]}),"\n",(0,a.jsxs)(t.p,{children:["Now the ops payoff. For any token already in the sequence, its key and its value never change once computed \u2014 the sign and the note are fixed. Only the ",(0,a.jsx)(t.em,{children:"query"})," is new for the token being generated right now. So the model computes every past token's key and value ",(0,a.jsx)(t.strong,{children:"once"})," and keeps them. That store is the KV cache. It literally holds the keys and values, because those are the parts that get reused on every future step. You can watch the reuse pay off by generating a long answer and reading the steady per-token decode time \u2014 no slow-down as the sequence grows, because earlier keys and values are read from cache, not recomputed:"]}),"\n",(0,a.jsx)(t.pre,{children:(0,a.jsx)(t.code,{className:"language-bash",children:'curl -s http://localhost:11434/api/generate -d \'{\n  "model": "qwen3:0.6b",\n  "prompt": "List, with one short line each, ten everyday tips for saving electricity at home. /no_think",\n  "stream": false,\n  "think": false\n}\' | jq \'{output_tokens: .eval_count,\n         decode_ms: (.eval_duration/1e6 | floor),\n         itl_ms: (.eval_duration/.eval_count/1e6 | floor),\n         tok_per_s: (.eval_count/(.eval_duration/1e9) | floor)}\'\n'})}),"\n",(0,a.jsx)(t.p,{children:(0,a.jsx)(t.strong,{children:"Expected output"})}),"\n",(0,a.jsx)(t.pre,{children:(0,a.jsx)(t.code,{className:"language-text",children:'{\n  "output_tokens": 119,\n  "decode_ms": 829,\n  "itl_ms": 6,\n  "tok_per_s": 143\n}\n'})}),"\n",(0,a.jsxs)(t.p,{children:["Your exact numbers will differ, but a steady ",(0,a.jsx)(t.code,{children:"itl_ms"})," (a few milliseconds per token) across a long answer is the cache working. If every token re-read the whole history from scratch, ",(0,a.jsx)(t.code,{children:"itl_ms"})," would climb as the sequence grew, and it does not. This is also why the KV cache is your capacity ceiling: it is the price you pay to keep decode flat."]}),"\n",(0,a.jsx)(t.mermaid,{value:'flowchart LR\n  Q["new token\'s query"] --\x3e M["match against<br/>every past key"]\n  KV["KV cache<br/>keys + values<br/>(computed once, kept)"] --\x3e M\n  M --\x3e W["blend the matched<br/>values by weight"]\n  W --\x3e NT["contributes to<br/>next-token prediction"]'}),"\n",(0,a.jsx)(t.h2,{id:"2--temperature-0-is-not-reproducible",children:'2 \u2014 Temperature 0 is not "reproducible"'}),"\n",(0,a.jsxs)(t.p,{children:["Here is a mistake that bites eval pipelines. You want your golden eval suite to give the same score every run, so you set ",(0,a.jsx)(t.code,{children:"temperature: 0"})," and call it deterministic. Then you move the model from Ollama to vLLM, or upgrade a driver, and the scores shift by a point or two with no change to the prompts. You spend an afternoon hunting a bug that is not there."]}),"\n",(0,a.jsx)(t.p,{children:"First, the sampling knobs, plainly. After the model predicts the next token it does not get one answer \u2014 it gets a probability spread over the whole dictionary. The sampling parameters decide how you pick from that spread:"}),"\n",(0,a.jsxs)(t.ul,{children:["\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"temperature"})," \u2014 how flat or peaked the spread is. High temperature flattens it (more surprising, more varied). ",(0,a.jsx)(t.code,{children:"temperature: 0"}),' means "always take the single most likely token", which is called greedy decoding.']}),"\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"top-p"})," \u2014 keep only the smallest set of tokens whose probabilities add up to p, then pick from those. A dynamic shortlist."]}),"\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"top-k"})," \u2014 keep only the k most likely tokens, then pick. A fixed-size shortlist."]}),"\n"]}),"\n",(0,a.jsxs)(t.p,{children:["Greedy decoding (",(0,a.jsx)(t.code,{children:"temperature: 0"}),") is deterministic ",(0,a.jsx)(t.em,{children:"on one engine, one build, one machine"}),". Run the same greedy request twice on your host and you get the same text:"]}),"\n",(0,a.jsx)(t.pre,{children:(0,a.jsx)(t.code,{className:"language-bash",children:'for i in 1 2; do\n  curl -s http://localhost:11434/api/generate -d \'{\n    "model": "qwen3:0.6b",\n    "prompt": "Name one benefit of drinking water regularly. Answer in one short sentence. /no_think",\n    "stream": false,\n    "think": false,\n    "options": {"temperature": 0, "seed": 42}\n  }\' | jq -r \'.response\'\ndone\n'})}),"\n",(0,a.jsx)(t.p,{children:(0,a.jsx)(t.strong,{children:"Expected output"})}),"\n",(0,a.jsx)(t.pre,{children:(0,a.jsx)(t.code,{className:"language-text",children:"Drinking water regularly helps maintain hydration and supports bodily functions.\nDrinking water regularly helps maintain hydration and supports bodily functions.\n"})}),"\n",(0,a.jsxs)(t.p,{children:["Two identical lines (the exact sentence will differ on your run; what matters is that the two lines match each other). So far so good. But that guarantee is ",(0,a.jsx)(t.strong,{children:"local"}),". Across engines, the tiny floating-point differences in how each one runs the matrix maths can tip a near-tie between two candidate tokens the other way, and from that point the two answers diverge. Greedy removes the ",(0,a.jsx)(t.em,{children:"sampling"})," randomness; it does not make two different engines compute bit-identical numbers. So ",(0,a.jsx)(t.code,{children:"temperature: 0"})," gives you repeatable scores on the ",(0,a.jsx)(t.em,{children:"same"}),' setup, which is what you want inside one CI job, but it is not a promise that Ollama and vLLM will score your eval set identically. When you compare engines in the serving module, pin the engine and build alongside the temperature, and treat a small cross-engine drift as expected, not as a regression. Frame your eval baselines as "on this engine, this build", and you will not chase ghosts.']}),"\n",(0,a.jsx)(t.h2,{id:"3--the-chat-template-the-wrapper-you-never-see",children:"3 \u2014 The chat template: the wrapper you never see"}),"\n",(0,a.jsxs)(t.p,{children:["When you send ",(0,a.jsx)(t.code,{children:'messages: [{"role": "user", "content": "hello"}]'}),", the model does not receive that JSON. It receives a single flat string, wrapped in special marker tokens that tell it where the system prompt ends, where the user turn starts, and where the assistant is expected to begin. That wrapper is the ",(0,a.jsx)(t.strong,{children:"chat template"}),', and it is baked into the model. Think of it as the printed form the counter clerk fills in from what you say: you speak plainly, but what goes into the system is a rigid form with boxes for "role" and "content" and a signature line. Get the form wrong and the request is misread, even though what you said was fine.']}),"\n",(0,a.jsx)(t.p,{children:"You can read the exact template shipped with the course model:"}),"\n",(0,a.jsx)(t.pre,{children:(0,a.jsx)(t.code,{className:"language-bash",children:"ollama show --template qwen3:0.6b\n"})}),"\n",(0,a.jsxs)(t.p,{children:[(0,a.jsx)(t.strong,{children:"Expected output"})," (the Go-template Ollama ships with the model; trimmed to the parts that matter here)"]}),"\n",(0,a.jsx)(t.pre,{children:(0,a.jsx)(t.code,{className:"language-text",children:'{{- range $i, $_ := .Messages }}\n{{- $last := eq (len (slice $.Messages $i)) 1 -}}\n{{- if eq .Role "user" }}<|im_start|>user\n{{ .Content }}\n{{- if and $.IsThinkSet (eq $i $lastUserIdx) }}\n   {{- if $.Think -}}\n      {{- " "}}/think\n   {{- else -}}\n      {{- " "}}/no_think\n   {{- end -}}\n{{- end }}<|im_end|>\n{{ else if eq .Role "assistant" }}<|im_start|>assistant\n{{ if (and $.IsThinkSet (and .Thinking (or $last (gt $i $lastUserIdx)))) -}}\n<think>{{ .Thinking }}</think>\n{{ end -}}\n...\n{{- if and (ne .Role "assistant") $last }}<|im_start|>assistant\n{{ if and $.IsThinkSet (not $.Think) -}}\n<think>\n\n</think>\n\n{{ end -}}\n'})}),"\n",(0,a.jsxs)(t.p,{children:["Look for the special markers (Qwen3 uses ",(0,a.jsx)(t.code,{children:"<|im_start|>"})," and ",(0,a.jsx)(t.code,{children:"<|im_end|>"})," around each role's turn) and for where the template opens the assistant's turn. Two ops facts fall straight out of this. First, this is where ",(0,a.jsx)(t.code,{children:"/no_think"})," and the ",(0,a.jsx)(t.code,{children:"think"})," parameter actually act \u2014 they toggle a branch in this template that either opens or suppresses a reasoning block before the answer. The control you used in the lab lives right here, in the wrapper. Second, this template is why a model has a fixed API contract: if a client sends the wrong markers, or you fine-tune on data that used a ",(0,a.jsx)(t.em,{children:"different"}),' template, the model gets a malformed form and quality quietly drops. When you package and fine-tune models later in the course, the chat template travels with the model as part of its contract, and matching it is not optional. A mismatched template is one of the most common and most invisible causes of "the fine-tuned model got worse".']}),"\n",(0,a.jsx)(t.h2,{id:"4--thinking-mode-one-level-down",children:"4 \u2014 Thinking mode, one level down"}),"\n",(0,a.jsxs)(t.p,{children:["The lab measured what thinking mode costs. Here is the mechanism, so you can reason about it rather than just avoid it. Thinking mode does not change the model or add a separate reasoning engine. It flips the chat-template branch from section 3 so the model first generates a bounded block of reasoning tokens, then its answer. Those reasoning tokens are ordinary decode steps \u2014 same ITL, same KV growth \u2014 there are just many more of them. Confirm the pattern: with thinking on, the response carries a separate reasoning field and a much larger ",(0,a.jsx)(t.code,{children:"eval_count"}),", while the visible answer stays short:"]}),"\n",(0,a.jsx)(t.pre,{children:(0,a.jsx)(t.code,{className:"language-bash",children:'curl -s http://localhost:11434/api/generate -d \'{\n  "model": "qwen3:0.6b",\n  "prompt": "Is 17 a prime number? Answer yes or no.",\n  "stream": false,\n  "think": true\n}\' | jq \'{output_tokens: .eval_count, thinking_chars: (.thinking | length), answer: .response}\'\n'})}),"\n",(0,a.jsx)(t.p,{children:(0,a.jsx)(t.strong,{children:"Expected output"})}),"\n",(0,a.jsx)(t.pre,{children:(0,a.jsx)(t.code,{className:"language-text",children:'{\n  "output_tokens": 457,\n  "thinking_chars": 1304,\n  "answer": "Yes, 17 is a prime number. A prime number is a number greater than 1 that has no divisors other than 1 and itself. When tested, 17 is not divisible by any number between 2 and 16, confirming that it is prime. \\n\\n**Answer:** Yes."\n}\n'})}),"\n",(0,a.jsxs)(t.p,{children:["A large ",(0,a.jsx)(t.code,{children:"output_tokens"}),", over a thousand ",(0,a.jsx)(t.code,{children:"thinking_chars"}),' of separate reasoning, and a short answer that carries the "yes". Your counts will differ, and this tiny model sometimes restates its reasoning in the answer too \u2014 but the pattern holds: the bulk of the generation is the reasoning field, not the visible reply. This is why pinning ',(0,a.jsx)(t.code,{children:"think: false"})," is a serving decision, not a style choice: with thinking on, your output token count per request swings wildly with the difficulty of the question, so your latency and your KV memory become unpredictable \u2014 the two things a production serving plan needs to be stable. You allow thinking only where the reasoning genuinely buys correctness, and you budget for its token blow-up when you do."]}),"\n",(0,a.jsx)(t.admonition,{title:"Where you will use this",type:"tip",children:(0,a.jsxs)(t.ul,{children:["\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"The KV cache holds keys and values because those are the parts attention reuses on every step."})," ",(0,a.jsx)(t.strong,{children:"Use it when:"})," you are sizing a serving box or reading an out-of-memory kill on a model server \u2014 the KV growth per token is a real memory line, and long contexts or high concurrency are what fill it."]}),"\n",(0,a.jsxs)(t.li,{children:[(0,a.jsxs)(t.strong,{children:[(0,a.jsx)(t.code,{children:"temperature: 0"})," is deterministic within one engine and build, not across them."]})," ",(0,a.jsx)(t.strong,{children:"Use it when:"})," an eval score drifts a point after an engine swap or driver upgrade \u2014 pin engine and build in your eval baseline before you open a bug, and treat small cross-engine drift as expected."]}),"\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"The chat template is the hidden contract every message goes through, and it travels with the model."})," ",(0,a.jsx)(t.strong,{children:"Use it when:"})," a fine-tuned or newly-packaged model quietly gets worse \u2014 check the template matches the one it was trained and served with (",(0,a.jsx)(t.code,{children:"ollama show --template"}),") before you suspect the weights."]}),"\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"Thinking mode is extra decode tokens toggled by the template, not a separate engine."})," ",(0,a.jsx)(t.strong,{children:"Use it when:"})," latency or token cost per request is swinging unpredictably \u2014 check whether reasoning mode is on; pin it off for factual workloads so your capacity numbers stay stable."]}),"\n"]})}),"\n",(0,a.jsx)(t.h2,{id:"teardown",children:"Teardown"}),"\n",(0,a.jsxs)(t.p,{children:["Nothing here seeded persistent state, so there is nothing to remove. Ollama stays running as your host model server for M2. If you want to free the model's memory now, ",(0,a.jsx)(t.code,{children:"ollama stop qwen3:0.6b"}),"; otherwise it unloads itself after the keep-alive window. Leave the model pulled \u2014 the next module uses it."]})]})}function c(e={}){let{wrapper:t}={...(0,o.R)(),...e.components};return t?(0,a.jsx)(t,{...e,children:(0,a.jsx)(d,{...e})}):d(e)}},8453(e,t,n){n.d(t,{R:()=>i,x:()=>r});var s=n(6540);let a={},o=s.createContext(a);function i(e){let t=s.useContext(o);return s.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:i(e.components),s.createElement(o.Provider,{value:t},e.children)}}}]);